mapper.select:
SELECT COALESCE(SUM(session_count), 0) AS sessionCount, COALESCE(SUM(page_view_count), 0) AS pageViewCount
FROM site_user_event_daily_session
WHERE event_date BETWEEN #{start} AND #{end}

SELECT referrer_host AS referrerHost, SUM(event_count) AS count
FROM site_user_event_daily_referrer
WHERE event_date BETWEEN #{start} AND #{end}
GROUP BY referrer_host
ORDER BY count DESC
LIMIT #{limit}
